// N-Queens II (#52) на битовых масках: занятые столбцы и диагонали — три int
int full = (1 << n) - 1, total = 0;
void Place(int cols, int d1, int d2) {
    if (cols == full) { total++; return; }
    int free = full & ~(cols | d1 | d2);       // свободные столбцы строки
    while (free != 0) {
        int bit = free & -free;                // младший свободный столбец
        free -= bit;
        Place(cols | bit, (d1 | bit) << 1, (d2 | bit) >> 1);
    }
}
